mapper.select:
SELECT FROM material m LEFT JOIN material_version v ON v.id = m.latest_version_id AND v.material_id = m.id LEFT JOIN material_processing_revision r ON r.version_id = v.id AND r.revision_no = (SELECT MAX(latest_r.revision_no) FROM material_processing_revision latest_r WHERE latest_r.version_id = v.id) WHERE m.owner_type = #{ownerType} AND m.owner_key = #{ownerKey} AND m.lifecycle_state = #{lifecycleState} AND EXISTS (SELECT 1 FROM material_scope_link library_scope WHERE library_scope.material_id = m.id AND library_scope.scope_type = 'LIBRARY' AND library_scope.scope_key IN ('personal', 'library', #{ownerKey}))
AND m.display_name LIKE CONCAT('%', #{query}, '%')
ORDER BY m.updated_at DESC, m.id LIMIT #{limit} OFFSET #{offset}
